import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, DoubleSide } from 'three/webgpu';
import { uv, mix, color, vec3, sin, fract, dot, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();
  group.name = 'collection-title';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- Backdrop panel: engineered vertical gradient + subtle static grain ----
  const panelWidth = 2.8;
  const panelHeight = 1.75; // matches ~1.6 atlas aspect (512x320)

  const gradientMat = new MeshBasicNodeMaterial();
  gradientMat.side = DoubleSide;
  gradientMat.transparent = true;

  const topColor = color(colors.ink);
  const bottomColor = color(colors.surface);
  const gradient = mix(bottomColor, topColor, uv().y);

  // static pseudo-random grain, no time dependency (static composition)
  const grainSeed = dot(uv(), vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453));
  const grainAmount = grain.mul(0.04).sub(0.02);

  gradientMat.colorNode = gradient.add(vec3(grainAmount, grainAmount, grainAmount));

  const panelGeo = new PlaneGeometry(panelWidth, panelHeight, 1, 1);
  const panel = new Mesh(panelGeo, gradientMat);
  panel.position.z = 0;
  group.add(panel);

  // ---- Accent underline rule ----
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = color(colors.accent);
  ruleMat.transparent = false;
  const ruleGeo = new PlaneGeometry(1.1, 0.03, 1, 1);
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(0, -0.5, 0.01);
  group.add(rule);

  // ---- Headline text: "Collection" ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? { text: 'Collection', typography: { fontSize: 96 } };

  const headline = ctx.fontAtlas.createText(headlineItem.text ?? 'Collection', {
    fontSize: headlineItem.typography?.fontSize ?? 96,
    color: colors.paper,
    align: 'center',
  });
  headline.position.set(0, 0.05, 0.02);
  group.add(headline);

  // ---- Motion: weighted rise-in + settle (no linear easing, static idle) ----
  const startY = group.position.y;
  const tl = gsap.timeline();
  gsap.set(group, { scale: 0.97 });
  gsap.set(headline.position, { y: headline.position.y - 0.2 });
  gsap.set(panel.material, { opacity: 0 });

  tl.to(panel.material, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0);
  tl.to(
    headline.position,
    { y: headline.position.y + 0.2, duration: 0.7, ease: 'power3.out' },
    0.05
  );
  tl.to(
    group.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power2.out' },
    0.1
  );
  tl.to(
    group.scale,
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0.55
  );

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(panel.material);
    gsap.killTweensOf(headline.position);
    gsap.killTweensOf(group.scale);

    panelGeo.dispose();
    gradientMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();

    if (headline.geometry) headline.geometry.dispose();
    if (headline.material) {
      if (headline.material.map) headline.material.map.dispose();
      headline.material.dispose();
    }

    group.remove(panel, rule, headline);
  };

  group.userData.handlers = {};

  return group;
}
